// Embeds the files in templates/ (the gzipped system disks and the data-disk boot sectors) in
// src/disk/Templates.ts as strings, so that the esbuild bundle and the single-file binaries carry them.
// The generated file is gitignored and regenerated before type checks, tests, and builds.
// src/disk/DiskTemplates.ts is the API to it.
//
// Run with "npm run generateTemplates -w packages/trs80-tool".

import fs from "fs";
import path from "path";
import {fileURLToPath} from "url";

const TEMPLATES_DIR = fileURLToPath(new URL("../templates", import.meta.url));
const OUTPUT_PATH = fileURLToPath(new URL("../src/disk/Templates.ts", import.meta.url));
const BOOT_SECTORS_FILENAME = "data-disk-boot-sectors.json";
const SYSTEM_DISK_SUFFIX = ".dmk.gz";

/**
 * How many characters of base64 go in each string literal in the output file.
 */
const CHARACTERS_PER_LITERAL = 120;

/**
 * Generate the source of a string constant, split into concatenated literals so that no line is enormous.
 *
 * @param indent what to put before each line.
 * @param text the string.
 * @param suffix what to put after the last literal.
 */
function generateStringLines(indent: string, text: string, suffix: string): string[] {
    const lines: string[] = [];
    for (let i = 0; i < text.length; i += CHARACTERS_PER_LITERAL) {
        const isLast = i + CHARACTERS_PER_LITERAL >= text.length;
        lines.push(indent + JSON.stringify(text.substring(i, i + CHARACTERS_PER_LITERAL)) + (isLast ? suffix : " +"));
    }
    if (text.length === 0) {
        lines.push(indent + "\"\"" + suffix);
    }
    return lines;
}

/**
 * Write the output file if its content changed.
 */
function main(): void {
    const lines: string[] = [];
    lines.push("// Generated by tools/GenerateTemplates.ts from the files in templates/. Do not modify.");
    lines.push("");

    lines.push("/**");
    lines.push(" * The bootable system disks: base64 of the gzipped DMK image, keyed by file name without \"" +
        SYSTEM_DISK_SUFFIX + "\".");
    lines.push(" */");
    lines.push("export const SYSTEM_DISK_TEMPLATES_BASE64: { [name: string]: string } = {");
    const systemDiskNames = fs.readdirSync(TEMPLATES_DIR)
        .filter(filename => filename.endsWith(SYSTEM_DISK_SUFFIX))
        .sort();
    for (const filename of systemDiskNames) {
        const name = filename.substring(0, filename.length - SYSTEM_DISK_SUFFIX.length);
        const base64 = fs.readFileSync(path.join(TEMPLATES_DIR, filename)).toString("base64");
        lines.push("    " + JSON.stringify(name) + ":");
        lines.push(... generateStringLines("        ", base64, ","));
    }
    lines.push("};");
    lines.push("");

    lines.push("/**");
    lines.push(" * The DOSes' data-disk boot sectors as hex strings, keyed as in " + BOOT_SECTORS_FILENAME + ".");
    lines.push(" */");
    const bootSectorsJson = fs.readFileSync(path.join(TEMPLATES_DIR, BOOT_SECTORS_FILENAME), "utf-8");
    const bootSectors = JSON.parse(bootSectorsJson) as { [key: string]: string[] };
    lines.push("export const DATA_DISK_BOOT_SECTORS_HEX: { [key: string]: string[] } = {");
    for (const key of Object.keys(bootSectors)) {
        lines.push("    " + JSON.stringify(key) + ": [");
        for (const hex of bootSectors[key]) {
            lines.push(... generateStringLines("        ", hex, ","));
        }
        lines.push("    ],");
    }
    lines.push("};");
    lines.push("");

    const content = lines.join("\n");
    let oldContent: string | undefined;
    try {
        oldContent = fs.readFileSync(OUTPUT_PATH, "utf-8");
    } catch (e) {
        oldContent = undefined;
    }
    if (content !== oldContent) {
        fs.writeFileSync(OUTPUT_PATH, content);
        console.log("Wrote src/disk/Templates.ts");
    }
}

main();
